@@ -0,0 +1,45 @@
+using System;
+using System.ComponentModel.DataAnnotations;
+
+namespace Fabrikam.Hrms.Core.Models
+{
+    /// <summary>
+    /// Extended employee profile data. Linked 1:1 with <see cref="User"/>.
+    /// Created lazily on first profile update -- not every user will have one.
+    /// </summary>
+    public class UserProfile
+    {
+        public int Id { get; set; }
+
+        [Required]
+        public int UserId { get; set; }
+
+        /// <summary>Optional freeform biography text (max 2000 chars).</summary>
+        [MaxLength(2000)]
+        public string? Bio { get; set; }
+
+        /// <summary>Fully-qualified URL to the user's avatar image.</summary>
+        [MaxLength(512)]
+        [Url]
+        public string? AvatarUrl { get; set; }
+
+        /// <summary>IANA time zone identifier, e.g. "America/New_York".</summary>
+        [MaxLength(100)]
+        public string? TimeZoneId { get; set; }
+
+        /// <summary>User's preferred pronouns, stored as-entered.</summary>
+        [MaxLength(50)]
+        public string? Pronouns { get; set; }
+
+        /// <summary>LinkedIn profile URL.</summary>
+        [MaxLength(512)]
+        [Url]
+        public string? LinkedInUrl { get; set; }
+
+        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
+        public DateTime? UpdatedAt { get; set; }
+
+        // Navigation property
+        public User User { get; set; } = null!;
+    }
+}

diff --git a/src/Core/Services/UserProfileService.cs b/src/Core/Services/UserProfileService.cs
