@@ -0,0 +1,72 @@
+using System;
+using System.Threading.Tasks;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.Logging;
+using Fabrikam.Hrms.Core.Interfaces;
+using Fabrikam.Hrms.Core.Models;
+using Fabrikam.Hrms.Infrastructure.Data;
+
+namespace Fabrikam.Hrms.Core.Services
+{
+    public class UserProfileService : IUserProfileService
+    {
+        private readonly AppDbContext _context;
+        private readonly ILogger<UserProfileService> _logger;
+
+        public UserProfileService(AppDbContext context, ILogger<UserProfileService> logger)
+        {
+            _context = context ?? throw new ArgumentNullException(nameof(context));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        public async Task<UserProfile?> GetByUserIdAsync(int userId)
+        {
+            return await _context.UserProfiles
+                .AsNoTracking()
+                .FirstOrDefaultAsync(p => p.UserId == userId);
+        }
+
+        public async Task<UserProfile> UpsertAsync(int userId, UserProfileUpdateRequest request)
+        {
+            var profile = await _context.UserProfiles
+                .FirstOrDefaultAsync(p => p.UserId == userId);
+
+            if (profile == null)
+            {
+                profile = new UserProfile { UserId = userId };
+                _context.UserProfiles.Add(profile);
+            }
+
+            profile.Bio = request.Bio;
+            profile.AvatarUrl = request.AvatarUrl;
+            profile.TimeZoneId = request.TimeZoneId;
+            profile.Pronouns = request.Pronouns;
+            profile.LinkedInUrl = request.LinkedInUrl;
+            profile.UpdatedAt = DateTime.UtcNow;
+
+            await _context.SaveChangesAsync();
+            _logger.LogInformation("Profile upserted for user {UserId}", userId);
+            return profile;
+        }
+
+        public async Task<bool> DeleteAsync(int userId)
+        {
+            var profile = await _context.UserProfiles
+                .FirstOrDefaultAsync(p => p.UserId == userId);
+
+            if (profile == null)
+                return false;
+
+            _context.UserProfiles.Remove(profile);
+            await _context.SaveChangesAsync();
+            _logger.LogInformation("Profile deleted for user {UserId}", userId);
+            return true;
+        }
+
+        public async Task<bool> AvatarUrlExistsAsync(string url)
+        {
+            return await _context.UserProfiles
+                .AnyAsync(p => p.AvatarUrl == url);
+        }
+    }
+}

