+using System;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.Extensions.Logging;
+using Fabrikam.Hrms.Core.Interfaces;
+using Fabrikam.Hrms.Core.Models;
+
+namespace Fabrikam.Hrms.API.Controllers
+{
+    [ApiController]
+    [Route("api/users/{userId:int}/profile")]
+    [Authorize]
+    [Produces("application/json")]
+    public class UserProfileController : ControllerBase
+    {
+        private readonly IUserProfileService _profileService;
+        private readonly ILogger<UserProfileController> _logger;
+
+        public UserProfileController(
+            IUserProfileService profileService,
+            ILogger<UserProfileController> logger)
+        {
+            _profileService = profileService ?? throw new ArgumentNullException(nameof(profileService));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        [HttpGet]
+        [ProducesResponseType(typeof(UserProfile), 200)]
+        [ProducesResponseType(204)]
+        public async Task<IActionResult> Get(int userId)
+        {
+            var profile = await _profileService.GetByUserIdAsync(userId);
+            if (profile == null)
+                return NoContent();
+
+            return Ok(profile);
+        }
+
+        [HttpPut]
+        [ProducesResponseType(typeof(UserProfile), 200)]
+        [ProducesResponseType(typeof(ValidationProblemDetails), 400)]
+        public async Task<IActionResult> Upsert(int userId, [FromBody] UserProfileUpdateRequest request)
+        {
+            if (!ModelState.IsValid)
+                return BadRequest(ModelState);
+
+            var callerId = int.Parse(User.FindFirst("id")?.Value ?? "0");
+            if (callerId != userId && !User.IsInRole("Admin"))
+                return Forbid();
+
+            var profile = await _profileService.UpsertAsync(userId, request);
+            return Ok(profile);
+        }
+
+        [HttpDelete]
+        [Authorize(Roles = "Admin")]
+        [ProducesResponseType(204)]
+        [ProducesResponseType(404)]
+        public async Task<IActionResult> Delete(int userId)
+        {
+            var deleted = await _profileService.DeleteAsync(userId);
+            if (!deleted)
+                return NotFound();
+
+            return NoContent();
+        }
+    }
+}

