@@ -0,0 +1,84 @@
+using System;
+using System.Collections.Generic;
+using System.Threading.Tasks;
+using Microsoft.Extensions.Configuration;
+using Microsoft.Extensions.Logging;
+using Stripe;
+using Northwind.Payments.Core.Models;
+
+namespace Northwind.Payments.Infrastructure.Gateways
+{
+    /// <summary>
+    /// Stripe implementation of <see cref="IPaymentGateway"/>.
+    /// Reads the API secret from IConfiguration ("Stripe:SecretKey").
+    /// </summary>
+    public class StripeGateway : IPaymentGateway
+    {
+        private readonly ILogger<StripeGateway> _logger;
+
+        public StripeGateway(IConfiguration configuration, ILogger<StripeGateway> logger)
+        {
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+            var secretKey = configuration["Stripe:SecretKey"]
+                ?? throw new InvalidOperationException("Stripe:SecretKey is not configured.");
+            StripeConfiguration.ApiKey = secretKey;
+        }
+
+        public async Task<GatewayChargeResult> ChargeAsync(GatewayChargeRequest request)
+        {
+            try
+            {
+                var options = new ChargeCreateOptions
+                {
+                    Amount = request.AmountInCents,
+                    Currency = request.Currency,
+                    Source = request.PaymentToken,
+                    Description = request.Description,
+                    Metadata = request.Metadata
+                };
+
+                var service = new ChargeService();
+                var charge = await service.CreateAsync(options);
+
+                return new GatewayChargeResult
+                {
+                    Success = charge.Status == "succeeded",
+                    TransactionId = charge.Id,
+                    ErrorMessage = charge.FailureMessage
+                };
+            }
+            catch (StripeException ex)
+            {
+                _logger.LogError(ex, "Stripe ChargeAsync failed: {Code} - {Message}",
+                    ex.StripeError?.Code, ex.Message);
+                return new GatewayChargeResult { Success = false, ErrorMessage = ex.Message };
+            }
+        }
+
+        public async Task<GatewayRefundResult> RefundAsync(GatewayRefundRequest request)
+        {
+            try
+            {
+                var options = new RefundCreateOptions
+                {
+                    Charge = request.ExternalTransactionId,
+                    Amount = request.AmountInCents
+                };
+
+                var service = new RefundService();
+                var refund = await service.CreateAsync(options);
+
+                return new GatewayRefundResult
+                {
+                    Success = refund.Status == "succeeded",
+                    TransactionId = refund.Id
+                };
+            }
+            catch (StripeException ex)
+            {
+                _logger.LogError(ex, "Stripe RefundAsync failed: {Message}", ex.Message);
+                return new GatewayRefundResult { Success = false, ErrorMessage = ex.Message };
+            }
+        }
+    }
+}

