index 0000000..a1b2c3d
--- /dev/null
+++ b/src/API/Middleware/RateLimitingMiddleware.cs
@@ -0,0 +1,84 @@
+using System;
+using System.Collections.Concurrent;
+using System.Net;
+using System.Text.Json;
+using System.Threading;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Http;
+using Microsoft.Extensions.Logging;
+using Microsoft.Extensions.Options;
+using MyApp.Core.Configuration;
+
+namespace MyApp.API.Middleware
+{
+    /// <summary>
+    /// Simple fixed-window rate limiting middleware. Tracks request counts per
+    /// client IP address within a configurable time window and returns HTTP 429
+    /// when the limit is exceeded. Uses an in-process ConcurrentDictionary --
+    /// for multi-instance deployments, replace with a distributed Redis counter.
+    /// </summary>
+    public class RateLimitingMiddleware
+    {
+        private readonly RequestDelegate _next;
+        private readonly RateLimitOptions _options;
+        private readonly ILogger<RateLimitingMiddleware> _logger;
+        private static readonly ConcurrentDictionary<string, (int Count, DateTime WindowStart)> _counters = new();
+
+        public RateLimitingMiddleware(
+            RequestDelegate next,
+            IOptions<RateLimitOptions> options,
+            ILogger<RateLimitingMiddleware> logger)
+        {
+            _next = next ?? throw new ArgumentNullException(nameof(next));
+            _options = options?.Value ?? throw new ArgumentNullException(nameof(options));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        public async Task InvokeAsync(HttpContext context)
+        {
+            if (!_options.Enabled)
+            {
+                await _next(context);
+                return;
+            }
+
+            var clientKey = GetClientKey(context);
+            var now = DateTime.UtcNow;
+
+            _counters.AddOrUpdate(clientKey,
+                key => (1, now),
+                (key, existing) =>
+                {
+                    if ((now - existing.WindowStart).TotalSeconds >= _options.WindowSeconds)
+                        return (1, now);
+                    return (existing.Count + 1, existing.WindowStart);
+                });
+
+            if (_counters.TryGetValue(clientKey, out var entry) && entry.Count > _options.MaxRequests)
+            {
+                _logger.LogWarning("Rate limit exceeded for {ClientKey} ({Count}/{Max})",
+                    clientKey, entry.Count, _options.MaxRequests);
+                context.Response.StatusCode = (int)HttpStatusCode.TooManyRequests;
+                context.Response.ContentType = "application/json";
+                context.Response.Headers["Retry-After"] = _options.WindowSeconds.ToString();
+                await context.Response.WriteAsync(JsonSerializer.Serialize(new
+                {
+                    status = 429,
+                    message = "Rate limit exceeded. Please slow down."
+                }));
+                return;
+            }
+
+            await _next(context);
+        }
+
+        private static string GetClientKey(HttpContext context)
+        {
+            var forwardedFor = context.Request.Headers["X-Forwarded-For"].FirstOrDefault();
+            if (!string.IsNullOrEmpty(forwardedFor))
+                return forwardedFor.Split(',')[0].Trim();
+
+            return context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
+        }
+    }
+}

