+using System;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.Diagnostics.HealthChecks;
+using Microsoft.Extensions.Logging;
+using MyApp.Infrastructure.Data;
+
+namespace MyApp.API.Controllers
+{
+    /// <summary>
+    /// Provides liveness and readiness probe endpoints for Kubernetes / load balancer health checks.
+    /// GET /health  -- liveness: returns 200 if the process is running
+    /// GET /ready   -- readiness: returns 200 only if DB is reachable
+    /// </summary>
+    [ApiController]
+    [Route("")]
+    [ApiExplorerSettings(IgnoreApi = true)]
+    public class HealthController : ControllerBase
+    {
+        private readonly AppDbContext _context;
+        private readonly ILogger<HealthController> _logger;
+
+        public HealthController(AppDbContext context, ILogger<HealthController> logger)
+        {
+            _context = context ?? throw new ArgumentNullException(nameof(context));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        /// <summary>Liveness probe -- always returns 200 if the process is alive.</summary>
+        [HttpGet("health")]
+        [ProducesResponseType(200)]
+        public IActionResult Health()
+        {
+            return Ok(new
+            {
+                status = "healthy",
+                timestamp = DateTime.UtcNow,
+                version = typeof(HealthController).Assembly.GetName().Version?.ToString()
+            });
+        }
+
+        /// <summary>Readiness probe -- returns 200 if the app is ready to serve traffic.</summary>
+        [HttpGet("ready")]
+        [ProducesResponseType(200)]
+        [ProducesResponseType(503)]
+        public async Task<IActionResult> Ready()
+        {
+            try
+            {
+                var canConnect = await _context.Database.CanConnectAsync();
+                if (!canConnect)
+                {
+                    _logger.LogWarning("Readiness check: database unreachable");
+                    return StatusCode(503, new { status = "unhealthy", reason = "database_unreachable" });
+                }
+
+                return Ok(new { status = "ready", timestamp = DateTime.UtcNow });
+            }
+            catch (Exception ex)
+            {
+                _logger.LogError(ex, "Readiness check threw an exception");
+                return StatusCode(503, new { status = "unhealthy", reason = ex.Message });
+            }
+        }
+    }
+}

