+  userId: number;
+}
+
+/**
+ * Main dashboard page for authenticated users. Displays a summary of the
+ * user's activity, quick-action shortcuts, and a live activity feed.
+ * Intended to be lazy-loaded via React.lazy() from App.tsx.
+ */
+export const UserDashboard: React.FC<UserDashboardProps> = ({ userId }) => {
+  const navigate = useNavigate();
+  const { user, stats, recentActivity, isLoading, error, refetch } = useUserData(userId);
+
+  const handleNewOrder = useCallback(() => navigate('/orders/new'), [navigate]);
+  const handleViewProfile = useCallback(() => navigate(`/profile/${userId}`), [navigate, userId]);
+  const handleViewOrders = useCallback(() => navigate('/orders'), [navigate]);
+
+  if (isLoading) {
