@@ -0,0 +1,70 @@
+import { useEffect, useCallback, useReducer } from 'react';
+import { apiClient } from '../api/client';
+import type { User, UserStats, ActivityItem } from '../types/api';
+
+interface UserDataState {
+  user: User | null;
+  stats: UserStats | null;
+  recentActivity: ActivityItem[];
+  isLoading: boolean;
+  error: Error | null;
+}
+
+type UserDataAction =
+  | { type: 'FETCH_START' }
+  | { type: 'FETCH_SUCCESS'; payload: { user: User; stats: UserStats; activity: ActivityItem[] } }
+  | { type: 'FETCH_ERROR'; payload: Error };
+
+const initialState: UserDataState = {
+  user: null,
+  stats: null,
+  recentActivity: [],
+  isLoading: true,
+  error: null,
+};
+
+function reducer(state: UserDataState, action: UserDataAction): UserDataState {
+  switch (action.type) {
+    case 'FETCH_START':
+      return { ...state, isLoading: true, error: null };
+    case 'FETCH_SUCCESS':
+      return {
+        ...state,
+        isLoading: false,
+        user: action.payload.user,
+        stats: action.payload.stats,
+        recentActivity: action.payload.activity,
+      };
+    case 'FETCH_ERROR':
+      return { ...state, isLoading: false, error: action.payload };
+    default:
+      return state;
+  }
+}
+
+export function useUserData(userId: number) {
+  const [state, dispatch] = useReducer(reducer, initialState);
+
+  const fetchData = useCallback(async () => {
+    dispatch({ type: 'FETCH_START' });
+    try {
+      const [user, stats, activity] = await Promise.all([
+        apiClient.get<User>(`/users/${userId}`),
+        apiClient.get<UserStats>(`/users/${userId}/stats`),
+        apiClient.get<ActivityItem[]>(`/users/${userId}/activity?limit=10`),
+      ]);
+      dispatch({
+        type: 'FETCH_SUCCESS',
+        payload: { user: user.data, stats: stats.data, activity: activity.data },
+      });
+    } catch (err) {
+      dispatch({ type: 'FETCH_ERROR', payload: err instanceof Error ? err : new Error(String(err)) });
+    }
+  }, [userId]);
+
+  useEffect(() => {
+    fetchData();
+  }, [fetchData]);
+
+  return { ...state, refetch: fetchData };
+}

