+++ b/src/services/SessionStore.ts
@@ -0,0 +1,79 @@
+import { Redis } from 'ioredis';
+import { logger } from '../utils/logger';
+import { UserPayload } from '../types/auth';
+
+const SESSION_PREFIX = 'session:';
+const DEFAULT_TTL_SECONDS = 3600;
+
+/**
+ * Wraps the raw Redis client with session-specific logic.
+ * Using a dedicated class (rather than calling redisClient directly from
+ * middleware) lets us:
+ *  - add retry / circuit-breaker logic in one place
+ *  - unit-test session logic without a live Redis instance
+ *  - swap Redis for another store (e.g., Valkey, DynamoDB) via DI
+ */
+export class SessionStore {
+  constructor(
+    private readonly redis: Redis,
+    private readonly ttlSeconds: number = DEFAULT_TTL_SECONDS
+  ) {}
+
+  /**
+   * Atomically creates a new session entry. Uses SET NX with an EX option so
+   * the create-and-expire is a single Redis command -- eliminates the race
+   * condition from the previous get-then-expire implementation.
+   */
+  async createSession(token: string, payload: UserPayload): Promise<boolean> {
+    const key = this.buildKey(token);
+    const result = await this.redis.set(
+      key,
+      JSON.stringify(payload),
+      'EX',
+      this.ttlSeconds,
+      'NX'
+    );
+    if (result !== 'OK') {
+      logger.warn({ token: token.slice(0, 8) }, 'Session create NX rejected -- token already exists');
+      return false;
+    }
+    return true;
+  }
+
+  async getSession(token: string): Promise<UserPayload | null> {
+    const key = this.buildKey(token);
+    const raw = await this.redis.get(key);
+    if (!raw) return null;
+
+    try {
+      return JSON.parse(raw) as UserPayload;
+    } catch (err) {
+      logger.error({ err, token: token.slice(0, 8) }, 'Failed to parse session payload from Redis');
+      return null;
+    }
+  }
+
+  /**
+   * Sliding expiry: refreshes the TTL on every authenticated request so
+   * active users are never logged out. Atomic EXPIRE command (single round-trip).
+   */
+  async refreshTtl(token: string): Promise<void> {
+    const key = this.buildKey(token);
+    await this.redis.expire(key, this.ttlSeconds);
+  }
+
+  async deleteSession(token: string): Promise<void> {
+    const key = this.buildKey(token);
+    await this.redis.del(key);
+    logger.info({ token: token.slice(0, 8) }, 'Session deleted');
+  }
+
+  async sessionExists(token: string): Promise<boolean> {
+    const key = this.buildKey(token);
+    return (await this.redis.exists(key)) === 1;
+  }
+
+  private buildKey(token: string): string {
+    return `${SESSION_PREFIX}${token}`;
+  }
+}

