@@ -0,0 +1,78 @@
+import { AxiosInstance, InternalAxiosRequestConfig } from 'axios';
+import { useAuthStore } from '../../store/auth';
+
+interface QueueEntry {
+  resolve: (token: string) => void;
+  reject: (reason: unknown) => void;
+}
+
+let isRefreshing = false;
+const pendingQueue: QueueEntry[] = [];
+
+function drainQueue(error: unknown, newToken: string | null): void {
+  pendingQueue.splice(0).forEach(({ resolve, reject }) => {
+    if (error) reject(error);
+    else resolve(newToken!);
+  });
+}
+
+/**
+ * Applies auth-related axios interceptors to the provided instance.
+ *
+ * Request interceptor: attaches Bearer token to every outgoing request.
+ * Response interceptor: on 401, silently refreshes the token and replays
+ * the original request. Concurrent 401s are queued to prevent a thundering
+ * herd of simultaneous refresh calls.
+ */
+export function applyAuthInterceptors(client: AxiosInstance): void {
+  client.interceptors.request.use(
+    (config: InternalAxiosRequestConfig) => {
+      const { accessToken } = useAuthStore();
+      if (accessToken) {
+        config.headers.Authorization = `Bearer ${accessToken}`;
+      }
+      return config;
+    },
+    (error) => Promise.reject(error)
+  );
+
+  client.interceptors.response.use(
+    (response) => response,
+    async (error) => {
+      const originalRequest = error.config as InternalAxiosRequestConfig & { _retried?: boolean };
+
+      if (error.response?.status !== 401 || originalRequest._retried) {
+        return Promise.reject(error);
+      }
+
+      if (isRefreshing) {
+        // Another refresh is already in flight -- queue this request until it resolves
+        return new Promise<string>((resolve, reject) => {
+          pendingQueue.push({ resolve, reject });
+        }).then((newToken) => {
+          originalRequest.headers.Authorization = `Bearer ${newToken}`;
+          return client(originalRequest);
+        });
+      }
+
+      originalRequest._retried = true;
+      isRefreshing = true;
+
+      try {
+        const store = useAuthStore();
+        const newToken = await store.refreshTokens();
+        drainQueue(null, newToken);
+        originalRequest.headers.Authorization = `Bearer ${newToken}`;
+        return client(originalRequest);
+      } catch (refreshError) {
+        drainQueue(refreshError, null);
+        const store = useAuthStore();
+        store.clearAuth();
+        window.location.replace('/login?reason=session_expired');
+        return Promise.reject(refreshError);
+      } finally {
+        isRefreshing = false;
+      }
+    }
+  );
+}

