@@ -0,0 +1,46 @@
+import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
+import { PageEvent } from '@angular/material/paginator';
+
+/**
+ * Thin wrapper around MatPaginator that enforces consistent defaults
+ * across the admin console. Sets standard page size options, always shows
+ * first/last buttons, and adds a results-count summary label above the paginator.
+ *
+ * Usage:
+ *   <app-paginator
+ *     [totalCount]="totalCount"
+ *     [pageSize]="pageSize"
+ *     (pageChanged)="onPageChange($event)">
+ *   </app-paginator>
+ */
+@Component({
+  selector: 'app-paginator',
+  templateUrl: './paginator.component.html',
+  styleUrls: ['./paginator.component.scss'],
+  changeDetection: ChangeDetectionStrategy.OnPush
+})
+export class PaginatorComponent {
+  @Input() totalCount = 0;
+  @Input() pageSize = 25;
+  @Input() pageIndex = 0;
+  @Output() pageChanged = new EventEmitter<PageEvent>();
+
+  readonly pageSizeOptions = [25, 50, 100];
+
+  get fromRecord(): number {
+    return this.totalCount === 0 ? 0 : this.pageIndex * this.pageSize + 1;
+  }
+
+  get toRecord(): number {
+    return Math.min((this.pageIndex + 1) * this.pageSize, this.totalCount);
+  }
+
+  get summaryLabel(): string {
+    if (this.totalCount === 0) return 'No results';
+    return `Showing ${this.fromRecord}–${this.toRecord} of ${this.totalCount.toLocaleString()} results`;
+  }
+
+  onPage(event: PageEvent): void {
+    this.pageChanged.emit(event);
+  }
+}

