diff --git a/src/queues/emailQueue.ts b/src/queues/emailQueue.ts
new file mode 100644
index 0000000..b2c3d4e
--- /dev/null
+++ b/src/queues/emailQueue.ts
@@ -0,0 +1,57 @@
+import Bull from 'bull';
+import { logger } from '../utils/logger';
+import { EmailService } from '../services/EmailService';
+import { EmailPayload } from '../types/email';
+import { emailConfig } from '../config/email';
+
+const REDIS_URL = process.env.REDIS_URL;
+if (!REDIS_URL) throw new Error('REDIS_URL is required for the email queue');
+
+/**
+ * Bull queue for reliable transactional email delivery.
+ *
+ * Queue semantics:
+ *  - at-least-once delivery (Bull's Bull.Queue guarantees)
+ *  - 3 attempts with exponential back-off (5s, 25s, 125s)
+ *  - failed jobs retained in Redis for 7 days for debugging
+ *  - completed jobs auto-pruned after 1 hour
+ *
+ * The queue is defined here and shared between the producer (EmailService.enqueue)
+ * and the consumer (this file's process handler). In a multi-process deployment
+ * the consumer runs in a separate worker process that imports this file.
+ */
+export const emailQueue = new Bull<EmailPayload>('email', REDIS_URL, {
+  defaultJobOptions: {
+    attempts: 3,
+    backoff: { type: 'exponential', delay: 5000 },
+    removeOnComplete: { age: 3600 },
+    removeOnFail: { age: 60 * 60 * 24 * 7 },
+  },
+});
+
+emailQueue.on('error', (err) => logger.error({ err }, 'Email queue error'));
+emailQueue.on('failed', (job, err) =>
+  logger.warn({ jobId: job.id, to: job.data.to, attempts: job.attemptsMade, err }, 'Email job failed')
+);
+emailQueue.on('completed', (job) =>
+  logger.info({ jobId: job.id, to: job.data.to }, 'Email job completed')
+);
+emailQueue.on('stalled', (job) =>
+  logger.warn({ jobId: job.id }, 'Email job stalled -- will be retried')
+);
+
+/**
+ * Registers the queue worker. Must be called once in the worker process entrypoint.
+ * Not called in the web server process to prevent unintended dual processing.
+ */
+export function startEmailWorker(): void {
+  const emailService = new EmailService(emailConfig);
+
+  emailQueue.process('send', 5, async (job) => {
+    const payload = job.data;
+    logger.debug({ jobId: job.id, to: payload.to, template: payload.template }, 'Processing email job');
+    await emailService.send(payload);
+  });
+
+  logger.info('Email queue worker started (concurrency=5)');
+}

