+/**
+ * Email worker process entrypoint.
+ * Run this as a separate process in production:
+ *   node dist/workers/emailWorker.js
+ *
+ * In development, ts-node-dev restarts it automatically on file changes.
+ * In Kubernetes, this runs as a separate Deployment (email-worker) with
+ * its own scaling policy independent of the web API pods.
+ */
+import 'dotenv/config';
+import { logger } from '../utils/logger';
+import { startEmailWorker } from '../queues/emailQueue';
+
+process.on('uncaughtException', (err) => {
+  logger.fatal({ err }, 'Uncaught exception in email worker -- exiting');
+  process.exit(1);
+});
+
+process.on('unhandledRejection', (reason) => {
+  logger.fatal({ reason }, 'Unhandled promise rejection in email worker -- exiting');
+  process.exit(1);
+});
+
+async function main(): Promise<void> {
+  logger.info('Starting email worker process');
+  startEmailWorker();
+
+  process.on('SIGTERM', async () => {
+    logger.info('SIGTERM received, draining email queue...');
+    // Allow in-flight jobs to complete
+    await new Promise<void>(resolve => setTimeout(resolve, 5000));
+    process.exit(0);
+  });
+
+  process.on('SIGINT', async () => {
+    logger.info('SIGINT received, draining email queue...');
+    await new Promise<void>(resolve => setTimeout(resolve, 2000));
+    process.exit(0);
+  });
+
+  logger.info('Email worker is running and waiting for jobs');
+}
+
+main().catch((err) => {
+  logger.fatal({ err }, 'Email worker startup failed');
+  process.exit(1);
+});

