+            <>
+              <span className={styles.originalPrice}>{formatCurrency(product.originalPrice)}</span>
+              <span className={styles.salePrice}>{formatCurrency(product.price)}</span>
+            </>
+          ) : (
+            <span className={styles.price}>{formatCurrency(product.price)}</span>
+          )}
+        </div>
+        {product.rating !== undefined && (
+          <div className={styles.rating} aria-label={`${product.rating} out of 5 stars`}>
