+using System;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.SignalR;
+using Microsoft.Extensions.Logging;
+using Contoso.Store.Core.Interfaces;
+
+namespace Contoso.Store.API.Hubs
+{
+    /// <summary>
+    /// SignalR hub for real-time push notifications to the storefront SPA.
+    /// Clients must authenticate with a valid JWT before connecting (enforced
+    /// by the [Authorize] attribute + the hub's auth policy in Program.cs).
+    ///
+    /// Each connected user joins a personal group keyed by their user ID so
+    /// the server can push targeted messages without broadcasting to everyone.
+    ///
+    /// Client-side group name: "user:{userId}"
+    /// Events emitted: "notification.new", "notification.read_all"
+    /// </summary>
+    [Authorize]
+    public class NotificationHub : Hub
+    {
+        private readonly INotificationService _notificationService;
+        private readonly ILogger<NotificationHub> _logger;
+
+        public NotificationHub(INotificationService notificationService, ILogger<NotificationHub> logger)
+        {
+            _notificationService = notificationService ?? throw new ArgumentNullException(nameof(notificationService));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        public override async Task OnConnectedAsync()
+        {
+            var userId = Context.UserIdentifier
+                ?? throw new InvalidOperationException("NotificationHub: user identifier is null on connection");
+
+            await Groups.AddToGroupAsync(Context.ConnectionId, $"user:{userId}");
+            _logger.LogDebug("SignalR client connected: userId={UserId} connectionId={ConnId}", userId, Context.ConnectionId);
+            await base.OnConnectedAsync();
+        }
+
+        public override async Task OnDisconnectedAsync(Exception? exception)
+        {
+            var userId = Context.UserIdentifier;
+            if (userId != null)
+                await Groups.RemoveFromGroupAsync(Context.ConnectionId, $"user:{userId}");
+            if (exception != null)
+                _logger.LogWarning(exception, "SignalR client disconnected with error: userId={UserId}", userId);
+            await base.OnDisconnectedAsync(exception);
+        }
+
+        /// <summary>Called by clients to mark all unread notifications as read.</summary>
+        public async Task MarkAllRead()
+        {
+            var userId = int.Parse(Context.UserIdentifier!);
+            await _notificationService.MarkAllReadAsync(userId);
+            await Clients.Caller.SendAsync("notification.read_all");
+            _logger.LogInformation("All notifications marked read for user {UserId}", userId);
+        }
+    }
+}

