diff --git a/ClientApp/src/hooks/useNotifications.ts b/ClientApp/src/hooks/useNotifications.ts
new file mode 100644
index 0000000..c3d4e5f
--- /dev/null
+++ b/ClientApp/src/hooks/useNotifications.ts
@@ -0,0 +1,99 @@
+import { useEffect, useRef, useCallback, useReducer } from 'react';
+import * as signalR from '@microsoft/signalr';
+import { apiClient } from '../api/client';
+import type { Notification } from '../types/notification';
+
+interface NotificationsState {
+  notifications: Notification[];
+  unreadCount: number;
+  isConnected: boolean;
+  isLoading: boolean;
+  error: string | null;
+}
+
+type Action =
+  | { type: 'SET_NOTIFICATIONS'; payload: Notification[] }
+  | { type: 'SET_UNREAD_COUNT'; payload: number }
+  | { type: 'PUSH_NOTIFICATION'; payload: Notification }
+  | { type: 'MARK_ALL_READ' }
+  | { type: 'SET_CONNECTED'; payload: boolean }
+  | { type: 'SET_LOADING'; payload: boolean }
+  | { type: 'SET_ERROR'; payload: string | null };
+
+function reducer(state: NotificationsState, action: Action): NotificationsState {
+  switch (action.type) {
+    case 'SET_NOTIFICATIONS': return { ...state, notifications: action.payload, isLoading: false };
+    case 'SET_UNREAD_COUNT': return { ...state, unreadCount: action.payload };
+    case 'PUSH_NOTIFICATION': return {
+      ...state,
+      notifications: [action.payload, ...state.notifications],
+      unreadCount: state.unreadCount + 1
+    };
+    case 'MARK_ALL_READ': return {
+      ...state,
+      notifications: state.notifications.map(n => ({ ...n, isRead: true })),
+      unreadCount: 0
+    };
+    case 'SET_CONNECTED': return { ...state, isConnected: action.payload };
+    case 'SET_LOADING': return { ...state, isLoading: action.payload };
+    case 'SET_ERROR': return { ...state, error: action.payload };
+    default: return state;
+  }
+}
+
+/**
+ * Manages real-time notifications via SignalR + REST fallback.
+ * Establishes the SignalR connection on mount and tears it down on unmount.
+ * Reconnects automatically using SignalR's built-in exponential back-off.
+ */
+export function useNotifications() {
+  const [state, dispatch] = useReducer(reducer, {
+    notifications: [], unreadCount: 0, isConnected: false, isLoading: true, error: null
+  });
+  const hubRef = useRef<signalR.HubConnection | null>(null);
+
+  const fetchInitial = useCallback(async () => {
+    dispatch({ type: 'SET_LOADING', payload: true });
+    try {
+      const [notifs, count] = await Promise.all([
+        apiClient.get<Notification[]>('/api/notification?pageSize=20').then(r => r.data),
+        apiClient.get<number>('/api/notification/unread-count').then(r => r.data),
+      ]);
+      dispatch({ type: 'SET_NOTIFICATIONS', payload: notifs });
+      dispatch({ type: 'SET_UNREAD_COUNT', payload: count });
+    } catch {
+      dispatch({ type: 'SET_ERROR', payload: 'Failed to load notifications' });
+    }
+  }, []);
+
+  useEffect(() => {
+    fetchInitial();
+
+    const hub = new signalR.HubConnectionBuilder()
+      .withUrl('/hubs/notifications', {
+        accessTokenFactory: () => localStorage.getItem('auth:access_token') ?? ''
+      })
+      .withAutomaticReconnect()
+      .configureLogging(signalR.LogLevel.Warning)
+      .build();
+
+    hub.on('notification.new', (n: Notification) => dispatch({ type: 'PUSH_NOTIFICATION', payload: n }));
+    hub.on('notification.read_all', () => dispatch({ type: 'MARK_ALL_READ' }));
+    hub.onreconnecting(() => dispatch({ type: 'SET_CONNECTED', payload: false }));
+    hub.onreconnected(() => dispatch({ type: 'SET_CONNECTED', payload: true }));
+
+    hub.start()
+      .then(() => dispatch({ type: 'SET_CONNECTED', payload: true }))
+      .catch(err => dispatch({ type: 'SET_ERROR', payload: String(err) }));
+
+    hubRef.current = hub;
+    return () => { hub.stop(); };
+  }, [fetchInitial]);
+
+  const markAllRead = useCallback(async () => {
+    await apiClient.post('/api/notification/read-all');
+    dispatch({ type: 'MARK_ALL_READ' });
+  }, []);
+
+  return { ...state, markAllRead, refetch: fetchInitial };
+}

