+    setIsOpen(prev => !prev);
+  };
+
+  const handleMarkAllRead = async () => {
+    await markAllRead();
+  };
+
+  return (
+    <div className={styles.container} ref={containerRef}>
+      <button
+        className={styles.bell}
+        onClick={handleBellClick}
+        aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`}
+        aria-expanded={isOpen}>
+        <svg className={styles.icon} viewBox="0 0 24 24" aria-hidden="true">
+          <path d="M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6v-5c0-3.07-1.63-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.64 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2z"/>
+        </svg>
+        {unreadCount > 0 && (
+          <span className={styles.badge} aria-hidden="true">
+            {unreadCount > 99 ? '99+' : unreadCount}
+          </span>
+        )}
+        {!isConnected && <span className={styles.offlineIndicator} title="Offline — reconnecting..." />}
+      </button>
+
+      {isOpen && (
+        <div className={styles.dropdown} role="dialog" aria-label="Notifications panel">
+          <div className={styles.dropdownHeader}>
+            <span>Notifications</span>
+            {unreadCount > 0 && (
+              <button className={styles.markAllBtn} onClick={handleMarkAllRead}>
+                Mark all as read
+              </button>
+            )}
+          </div>
+          <ul className={styles.list} role="list">
+            {notifications.length === 0 ? (
+              <li className={styles.emptyMsg}>You're all caught up!</li>
+            ) : (
+              notifications.slice(0, 10).map(n => (
+                <li key={n.id} className={`${styles.item} ${!n.isRead ? styles.unread : ''}`}>
+                  <p className={styles.message}>{n.message}</p>
+                  <time className={styles.time}>
+                    {formatDistanceToNow(new Date(n.createdAt), { addSuffix: true })}
+                  </time>
+                </li>
+              ))
+            )}
+          </ul>
+        </div>
+      )}
+    </div>
+  );
+};

