+using System;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.Extensions.Logging;
+using Contoso.Store.Core.Interfaces;
+using Contoso.Store.Core.Models;
+
+namespace Contoso.Store.API.Controllers
+{
+    /// <summary>
+    /// Generates and streams downloadable reports in CSV or Excel format.
+    /// All endpoints require Admin or Finance role. Report generation is
+    /// synchronous for requests &lt;= 30 days; longer date ranges are async
+    /// (job-based) and the client polls GET /api/report/jobs/{jobId}/status.
+    /// </summary>
+    [ApiController]
+    [Route("api/[controller]")]
+    [Authorize(Roles = "Admin,Finance")]
+    [Produces("application/json")]
+    public class ReportController : ControllerBase
+    {
+        private readonly IReportService _reportService;
+        private readonly ILogger<ReportController> _logger;
+
+        public ReportController(IReportService reportService, ILogger<ReportController> logger)
+        {
+            _reportService = reportService ?? throw new ArgumentNullException(nameof(reportService));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        /// <summary>
+        /// Generates a sales summary report and streams it as a downloadable file.
+        /// Supports CSV and Excel (xlsx) output formats.
+        /// </summary>
+        [HttpGet("sales")]
+        [ProducesResponseType(typeof(FileResult), 200)]
+        [ProducesResponseType(typeof(ValidationProblemDetails), 400)]
+        public async Task<IActionResult> SalesReport(
+            [FromQuery] DateOnly from,
+            [FromQuery] DateOnly to,
+            [FromQuery] string format = "csv")
+        {
+            if (to < from)
+                return BadRequest(new { message = "'to' date must be on or after 'from' date." });
+
+            var span = to.DayNumber - from.DayNumber;
+            if (span > 365)
+                return BadRequest(new { message = "Date range cannot exceed 365 days. Use the async job endpoint for larger exports." });
+
+            var query = new SalesReportQuery { From = from, To = to };
+            _logger.LogInformation("Sales report requested by {User} for {From} - {To} ({Format})",
+                User.Identity?.Name, from, to, format);
+
+            if (format.Equals("xlsx", StringComparison.OrdinalIgnoreCase))
+            {
+                var xlsx = await _reportService.GenerateSalesExcelAsync(query);
+                return File(xlsx, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
+                    $"sales-report-{from:yyyy-MM-dd}-to-{to:yyyy-MM-dd}.xlsx");
+            }
+
+            var csv = await _reportService.GenerateSalesCsvAsync(query);
+            return File(csv, "text/csv", $"sales-report-{from:yyyy-MM-dd}-to-{to:yyyy-MM-dd}.csv");
+        }
+
+        /// <summary>Generates a product performance report for the specified date range.</summary>
+        [HttpGet("products")]
+        [ProducesResponseType(typeof(FileResult), 200)]
+        public async Task<IActionResult> ProductReport(
+            [FromQuery] DateOnly from,
+            [FromQuery] DateOnly to,
+            [FromQuery] string format = "csv",
+            [FromQuery] string? category = null)
+        {
+            if (to < from)
+                return BadRequest(new { message = "'to' must be on or after 'from'." });
+
+            var query = new ProductReportQuery { From = from, To = to, Category = category };
+            if (format.Equals("xlsx", StringComparison.OrdinalIgnoreCase))
+            {
+                var xlsx = await _reportService.GenerateProductExcelAsync(query);
+                return File(xlsx, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
+                    $"product-report-{from:yyyy-MM-dd}-to-{to:yyyy-MM-dd}.xlsx");
+            }
+            var csv = await _reportService.GenerateProductCsvAsync(query);
+            return File(csv, "text/csv", $"product-report-{from:yyyy-MM-dd}-to-{to:yyyy-MM-dd}.csv");
+        }
+
+        /// <summary>Returns available date range presets for the report UI (e.g. Last 7 days, MTD).</summary>
+        [HttpGet("presets")]
+        [ProducesResponseType(typeof(object), 200)]
+        public IActionResult GetPresets()
+        {
+            var today = DateOnly.FromDateTime(DateTime.UtcNow);
+            return Ok(new
+            {
+                last7Days = new { from = today.AddDays(-7), to = today },
+                last30Days = new { from = today.AddDays(-30), to = today },
+                monthToDate = new { from = new DateOnly(today.Year, today.Month, 1), to = today },
+                yearToDate = new { from = new DateOnly(today.Year, 1, 1), to = today }
+            });
+        }
+    }
+}

