@@ -0,0 +1,120 @@
+using System;
+using System.Collections.Generic;
+using System.IO;
+using System.Linq;
+using System.Text;
+using System.Threading.Tasks;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.Logging;
+using Contoso.Store.Core.Interfaces;
+using Contoso.Store.Core.Models;
+using Contoso.Store.Infrastructure.Data;
+using Contoso.Store.Infrastructure.Exporters;
+
+namespace Contoso.Store.Core.Services
+{
+    public class ReportService : IReportService
+    {
+        private readonly AppDbContext _context;
+        private readonly ExcelExporter _excelExporter;
+        private readonly ILogger<ReportService> _logger;
+
+        public ReportService(AppDbContext context, ExcelExporter excelExporter, ILogger<ReportService> logger)
+        {
+            _context = context ?? throw new ArgumentNullException(nameof(context));
+            _excelExporter = excelExporter ?? throw new ArgumentNullException(nameof(excelExporter));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        public async Task<byte[]> GenerateSalesCsvAsync(SalesReportQuery query)
+        {
+            var rows = await FetchSalesRowsAsync(query);
+            var sb = new StringBuilder();
+            sb.AppendLine("Date,OrderId,CustomerEmail,ProductName,Quantity,UnitPrice,LineTotal,PaymentMethod,Status");
+            foreach (var r in rows)
+                sb.AppendLine($"{r.Date:yyyy-MM-dd},{r.OrderId},{r.CustomerEmail},{EscapeCsv(r.ProductName)},{r.Quantity},{r.UnitPrice:F2},{r.LineTotal:F2},{r.PaymentMethod},{r.Status}");
+            return Encoding.UTF8.GetBytes(sb.ToString());
+        }
+
+        public async Task<byte[]> GenerateSalesExcelAsync(SalesReportQuery query)
+        {
+            var rows = await FetchSalesRowsAsync(query);
+            var headers = new[] { "Date", "Order ID", "Customer", "Product", "Qty", "Unit Price", "Line Total", "Payment", "Status" };
+            var data = rows.Select(r => new object[] {
+                r.Date.ToString("yyyy-MM-dd"), r.OrderId, r.CustomerEmail,
+                r.ProductName, r.Quantity, r.UnitPrice, r.LineTotal, r.PaymentMethod, r.Status
+            }).ToList();
+            return _excelExporter.Export("Sales Report", headers, data);
+        }
+
+        public async Task<byte[]> GenerateProductCsvAsync(ProductReportQuery query)
+        {
+            var rows = await FetchProductRowsAsync(query);
+            var sb = new StringBuilder();
+            sb.AppendLine("ProductId,Name,Category,TotalSold,TotalRevenue,AvgRating,ReturnRate");
+            foreach (var r in rows)
+                sb.AppendLine($"{r.ProductId},{EscapeCsv(r.Name)},{EscapeCsv(r.Category)},{r.TotalSold},{r.TotalRevenue:F2},{r.AvgRating:F2},{r.ReturnRate:P1}");
+            return Encoding.UTF8.GetBytes(sb.ToString());
+        }
+
+        public async Task<byte[]> GenerateProductExcelAsync(ProductReportQuery query)
+        {
+            var rows = await FetchProductRowsAsync(query);
+            var headers = new[] { "Product ID", "Name", "Category", "Total Sold", "Revenue", "Avg Rating", "Return Rate" };
+            var data = rows.Select(r => new object[] {
+                r.ProductId, r.Name, r.Category, r.TotalSold, r.TotalRevenue, r.AvgRating, r.ReturnRate
+            }).ToList();
+            return _excelExporter.Export("Product Performance", headers, data);
+        }
+
+        private async Task<IReadOnlyList<SalesReportRow>> FetchSalesRowsAsync(SalesReportQuery query)
+        {
+            return await _context.OrderItems
+                .AsNoTracking()
+                .Where(oi => oi.Order.PaidAt.HasValue &&
+                             DateOnly.FromDateTime(oi.Order.PaidAt!.Value) >= query.From &&
+                             DateOnly.FromDateTime(oi.Order.PaidAt!.Value) <= query.To)
+                .Select(oi => new SalesReportRow
+                {
+                    Date = DateOnly.FromDateTime(oi.Order.PaidAt!.Value),
+                    OrderId = oi.OrderId,
+                    CustomerEmail = oi.Order.CustomerEmail,
+                    ProductName = oi.Product.Name,
+                    Quantity = oi.Quantity,
+                    UnitPrice = oi.UnitPrice,
+                    LineTotal = oi.UnitPrice * oi.Quantity,
+                    PaymentMethod = oi.Order.PaymentMethod ?? "unknown",
+                    Status = oi.Order.Status.ToString()
+                })
+                .ToListAsync();
+        }
+
+        private async Task<IReadOnlyList<ProductReportRow>> FetchProductRowsAsync(ProductReportQuery query)
+        {
+            var q = _context.OrderItems.AsNoTracking()
+                .Where(oi => oi.Order.PaidAt.HasValue &&
+                             DateOnly.FromDateTime(oi.Order.PaidAt!.Value) >= query.From &&
+                             DateOnly.FromDateTime(oi.Order.PaidAt!.Value) <= query.To);
+
+            if (!string.IsNullOrWhiteSpace(query.Category))
+                q = q.Where(oi => oi.Product.Category == query.Category);
+
+            return await q.GroupBy(oi => new { oi.ProductId, oi.Product.Name, oi.Product.Category })
+                .Select(g => new ProductReportRow
+                {
+                    ProductId = g.Key.ProductId,
+                    Name = g.Key.Name,
+                    Category = g.Key.Category,
+                    TotalSold = g.Sum(oi => oi.Quantity),
+                    TotalRevenue = g.Sum(oi => oi.UnitPrice * oi.Quantity),
+                    AvgRating = 0, // populated from ratings table in follow-up
+                    ReturnRate = 0
+                })
+                .OrderByDescending(r => r.TotalRevenue)
+                .ToListAsync();
+        }
+
+        private static string EscapeCsv(string value) =>
+            value.Contains(',') || value.Contains('"') ? $""{value.Replace(""", """")}"" : value;
+    }
+}

