@@ -0,0 +1,90 @@
+using System;
+using System.Collections.Generic;
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.Extensions.Logging;
+using Contoso.Store.Core.Interfaces;
+using Contoso.Store.Core.Models;
+
+namespace Contoso.Store.API.Controllers
+{
+    /// <summary>
+    /// Manages feature flags for gradual feature rollouts and A/B testing.
+    ///
+    /// GET /api/featureflag          — returns all flags (Admin only)
+    /// GET /api/featureflag/active   — returns flags active for the current caller
+    ///                                 (unauthenticated: global flags only)
+    /// POST/PATCH/DELETE             — Admin only (mutate flag definitions)
+    ///
+    /// The SPA calls GET /api/featureflag/active on app init and caches the
+    /// result in React context. Individual components read flags via the
+    /// useFeatureFlag('flag-name') hook without additional network calls.
+    /// </summary>
+    [ApiController]
+    [Route("api/[controller]")]
+    [Produces("application/json")]
+    public class FeatureFlagController : ControllerBase
+    {
+        private readonly IFeatureFlagService _featureFlagService;
+        private readonly ILogger<FeatureFlagController> _logger;
+
+        public FeatureFlagController(IFeatureFlagService featureFlagService, ILogger<FeatureFlagController> logger)
+        {
+            _featureFlagService = featureFlagService ?? throw new ArgumentNullException(nameof(featureFlagService));
+            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
+        }
+
+        /// <summary>Returns the set of feature flags currently enabled for the calling user.</summary>
+        [HttpGet("active")]
+        [ProducesResponseType(typeof(IReadOnlyList<string>), 200)]
+        public async Task<IActionResult> GetActiveForCaller()
+        {
+            int? userId = null;
+            if (User.Identity?.IsAuthenticated == true)
+                userId = int.TryParse(User.FindFirst("id")?.Value, out var id) ? id : null;
+
+            var activeFlags = await _featureFlagService.GetActiveForUserAsync(userId);
+            return Ok(activeFlags);
+        }
+
+        /// <summary>Returns all flag definitions. Admin only.</summary>
+        [HttpGet]
+        [Authorize(Roles = "Admin")]
+        [ProducesResponseType(typeof(IReadOnlyList<FeatureFlag>), 200)]
+        public async Task<IActionResult> GetAll()
+        {
+            var flags = await _featureFlagService.GetAllAsync();
+            return Ok(flags);
+        }
+
+        /// <summary>Creates or replaces a feature flag definition.</summary>
+        [HttpPut("{name}")]
+        [Authorize(Roles = "Admin")]
+        [ProducesResponseType(typeof(FeatureFlag), 200)]
+        [ProducesResponseType(typeof(ValidationProblemDetails), 400)]
+        public async Task<IActionResult> Upsert(string name, [FromBody] UpsertFeatureFlagRequest request)
+        {
+            if (!ModelState.IsValid)
+                return BadRequest(ModelState);
+
+            var flag = await _featureFlagService.UpsertAsync(name, request);
+            _logger.LogInformation("Feature flag '{Name}' upserted by {User}: enabled={Enabled}",
+                name, User.Identity?.Name, request.Enabled);
+            return Ok(flag);
+        }
+
+        /// <summary>Deletes a feature flag definition.</summary>
+        [HttpDelete("{name}")]
+        [Authorize(Roles = "Admin")]
+        [ProducesResponseType(204)]
+        [ProducesResponseType(404)]
+        public async Task<IActionResult> Delete(string name)
+        {
+            var deleted = await _featureFlagService.DeleteAsync(name);
+            if (!deleted) return NotFound();
+            _logger.LogWarning("Feature flag '{Name}' deleted by {User}", name, User.Identity?.Name);
+            return NoContent();
+        }
+    }
+}

