@@ -0,0 +1,67 @@
+import React, { createContext, useContext, useEffect, useReducer, useCallback } from 'react';
+import { apiClient } from '../api/client';
+
+interface FeatureFlagState {
+  flags: Set<string>;
+  isLoading: boolean;
+  error: string | null;
+}
+
+type FeatureFlagAction =
+  | { type: 'LOAD_START' }
+  | { type: 'LOAD_SUCCESS'; payload: string[] }
+  | { type: 'LOAD_ERROR'; payload: string };
+
+function reducer(state: FeatureFlagState, action: FeatureFlagAction): FeatureFlagState {
+  switch (action.type) {
+    case 'LOAD_START': return { ...state, isLoading: true, error: null };
+    case 'LOAD_SUCCESS': return { flags: new Set(action.payload), isLoading: false, error: null };
+    case 'LOAD_ERROR': return { ...state, isLoading: false, error: action.payload };
+    default: return state;
+  }
+}
+
+const FeatureFlagContext = createContext<{
+  flags: Set<string>;
+  isLoading: boolean;
+  isEnabled: (name: string) => boolean;
+  reload: () => Promise<void>;
+} | null>(null);
+
+/**
+ * Provides feature flag state to the entire React tree.
+ * Loads the active flags for the current user on mount and exposes
+ * isEnabled(flagName) for point-of-use checks without additional hooks.
+ *
+ * Place this near the root of the component tree, inside AuthProvider
+ * so user identity is available when fetching flag eligibility.
+ */
+export const FeatureFlagProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
+  const [state, dispatch] = useReducer(reducer, { flags: new Set<string>(), isLoading: true, error: null });
+
+  const load = useCallback(async () => {
+    dispatch({ type: 'LOAD_START' });
+    try {
+      const response = await apiClient.get<string[]>('/api/featureflag/active');
+      dispatch({ type: 'LOAD_SUCCESS', payload: response.data });
+    } catch (err) {
+      dispatch({ type: 'LOAD_ERROR', payload: 'Failed to load feature flags' });
+    }
+  }, []);
+
+  useEffect(() => { load(); }, [load]);
+
+  const isEnabled = useCallback((name: string) => state.flags.has(name), [state.flags]);
+
+  return (
+    <FeatureFlagContext.Provider value={{ flags: state.flags, isLoading: state.isLoading, isEnabled, reload: load }}>
+      {children}
+    </FeatureFlagContext.Provider>
+  );
+};
+
+export function useFeatureFlagContext() {
+  const ctx = useContext(FeatureFlagContext);
+  if (!ctx) throw new Error('useFeatureFlagContext must be used inside FeatureFlagProvider');
+  return ctx;
+}

