+import { useFeatureFlagContext } from '../context/FeatureFlagContext';
+
+/**
+ * Returns whether a named feature flag is currently enabled for the user.
+ *
+ * @param name - The flag name as defined in the admin console (e.g. "new-checkout-flow")
+ * @returns true if the flag is in the user's active flag set, false otherwise.
+ *
+ * Usage:
+ *   const isNewCheckout = useFeatureFlag('new-checkout-flow');
+ *   if (isNewCheckout) { ... }
+ *
+ * The flag set is loaded once on app init by FeatureFlagProvider and cached
+ * in React context. There is no additional network call per invocation.
+ *
+ * If the flag context has not finished loading (isLoading=true), returns false
+ * to prevent premature feature exposure during the initial render.
+ */
+export function useFeatureFlag(name: string): boolean {
+  const { isEnabled, isLoading } = useFeatureFlagContext();
+  if (isLoading) return false;
+  return isEnabled(name);
+}
+
+/**
+ * Returns whether ALL of the given flags are enabled for the current user.
+ * Useful for features that depend on multiple flags being simultaneously active.
+ */
+export function useAllFeatureFlags(...names: string[]): boolean {
+  const { isEnabled, isLoading } = useFeatureFlagContext();
+  if (isLoading) return false;
+  return names.every(isEnabled);
+}
+
+/**
+ * Returns whether ANY of the given flags are enabled for the current user.
+ * Useful for showing a UI element when at least one of several flags is active.
+ */
+export function useAnyFeatureFlag(...names: string[]): boolean {
+  const { isEnabled, isLoading } = useFeatureFlagContext();
+  if (isLoading) return false;
+  return names.some(isEnabled);
+}

