+import React from 'react';
+import { useFeatureFlag } from '../../hooks/useFeatureFlag';
+
+interface FeatureGateProps {
+  /** Name of the feature flag to check. */
+  flag: string;
+  /** Content rendered when the flag is enabled. */
+  children: React.ReactNode;
+  /** Optional content rendered when the flag is disabled. */
+  fallback?: React.ReactNode;
+}
+
+/**
+ * Conditionally renders children based on a feature flag.
+ *
+ * Usage:
+ *   <FeatureGate flag="new-checkout-flow">
+ *     <NewCheckout />
+ *   </FeatureGate>
+ *
+ *   <FeatureGate flag="new-checkout-flow" fallback={<LegacyCheckout />}>
+ *     <NewCheckout />
+ *   </FeatureGate>
+ *
+ * The component renders nothing (null) during the initial flag load so there
+ * is no flash of the wrong content. If you need to show a skeleton during
+ * load, wrap the FeatureGate in a Suspense boundary or pass a loading
+ * placeholder via the fallback prop combined with useFeatureFlagContext().
+ */
+export const FeatureGate: React.FC<FeatureGateProps> = ({ flag, children, fallback = null }) => {
+  const isEnabled = useFeatureFlag(flag);
+  return isEnabled ? <>{children}</> : <>{fallback}</>;
+};
+
+/**
+ * Renders children only when ALL of the given flags are enabled.
+ */
+export const AllFeaturesGate: React.FC<{ flags: string[]; children: React.ReactNode; fallback?: React.ReactNode }> = ({
+  flags, children, fallback = null
+}) => {
+  const { isEnabled, isLoading } = require('../../context/FeatureFlagContext').useFeatureFlagContext();
+  if (isLoading) return null;
+  const allEnabled = flags.every(isEnabled);
+  return allEnabled ? <>{children}</> : <>{fallback}</>;
+};
